using Godot;
using System;

// ==================== 内置应急地图（BootMaps） ====================
// ✅ 开创人2026-11-18：把 campaigns 两张图编译进程序集——任何打包/任何设备上,
// 启动地图与用户战役目录永远不可能为空。FileAccess 失败时 BootMapLoader 回退本图;
// SeedUserCampaigns 负责把图写进 user://campaigns（玩家加图入口）。
[GlobalClass]
public partial class BootMaps : RefCounted
{
    public static string MainBattlefield => System.Text.Encoding.UTF8.GetString(Convert.FromBase64String(B64Main));
    public static string ZhuZhanchang   => System.Text.Encoding.UTF8.GetString(Convert.FromBase64String(B64Zy));

    // ✅ 战役菜单播种:user://campaigns 无 .txt 时写入内置图(优先复制 res://,失败用编译内置)
    public static void SeedUserCampaigns()
    {
        DirAccess.MakeDirRecursiveAbsolute("user://campaigns");
        var userDir = DirAccess.Open("user://campaigns");
        if (userDir != null)
            foreach (var f in userDir.GetFiles())
                if (f.EndsWith(".txt")) return;   // 玩家已有图,不覆盖
        bool seeded = false;
        var pack = DirAccess.Open("res://campaigns");
        if (pack != null)
        {
            foreach (var f in pack.GetFiles())
            {
                if (!f.EndsWith(".txt")) continue;
                using var src = FileAccess.Open($"res://campaigns/{f}", FileAccess.ModeFlags.Read);
                if (src == null) continue;
                using var dst = FileAccess.Open($"user://campaigns/{f}", FileAccess.ModeFlags.Write);
                if (dst == null) continue;
                dst.StoreString(src.GetAsText());
                seeded = true;
            }
        }
        if (!seeded)   // res:// 也没有(APK 打包缺文件)→ 编译内置兜底
        {
            WriteUserMap("main_battlefield.txt", MainBattlefield);
            WriteUserMap("主战场_100x15.txt", ZhuZhanchang);
        }
    }

    private static void WriteUserMap(string name, string content)
    {
        using var dst = FileAccess.Open($"user://campaigns/{name}", FileAccess.ModeFlags.Write);
        dst?.StoreString(content);
    }

    private const string B64Main =
        "";
    private const string B64Zy =
        "";
}
